import { describe, it, expect } from 'vitest';
import politiesAsset from './atlas-polities.json';
import extentsAsset from './atlas-polity-extents.json';
import atlasOverrides from './atlas-overrides.json';
import { politiesForYear } from '../lib/atlas';

// Schema and cross-reference guards for the polity outlines — see
// docs/ancient-atlas-plan.md §Phase 4. atlas-polities.json is GENERATED by
// scripts/build-atlas-polities.js from the hand-authored convex extents in
// atlas-polity-extents.json, clipped to Natural Earth land and lakes. Inland
// edges are still deliberately coarse teaching shapes (the `note` field says
// so), but the structure, and now the coastline itself, must hold.

// Every polygon ring in a feature, whether it is a Polygon or a MultiPolygon.
const ringsOf = (feature) => (feature.geometry.type === 'Polygon'
  ? feature.geometry.coordinates
  : feature.geometry.coordinates.flat());

function inRing(point, ring) {
  let inside = false;
  for (let i = 0, j = ring.length - 1; i < ring.length; j = i, i += 1) {
    const [xi, yi] = ring[i];
    const [xj, yj] = ring[j];
    if ((yi > point[1]) !== (yj > point[1])
      && point[0] < ((xj - xi) * (point[1] - yi)) / (yj - yi) + xi) inside = !inside;
  }
  return inside;
}

// Point-in-feature honouring holes, so "is the Dead Sea inside Judah" answers
// correctly rather than just testing the outer ring.
function inFeature(point, feature) {
  const polygons = feature.geometry.type === 'Polygon'
    ? [feature.geometry.coordinates]
    : feature.geometry.coordinates;
  return polygons.some(([outer, ...holes]) => inRing(point, outer)
    && !holes.some((hole) => inRing(point, hole)));
}

const polity = (slug) => politiesAsset.features.find((f) => f.properties.s === slug);
describe('atlas-polities.json', () => {
  it('documents itself as a coarse, non-authoritative outline', () => {
    expect(typeof politiesAsset.note).toBe('string');
    expect(politiesAsset.note.length).toBeGreaterThan(20);
  });

  it('is a valid, non-empty FeatureCollection', () => {
    expect(politiesAsset.type).toBe('FeatureCollection');
    expect(politiesAsset.features.length).toBeGreaterThan(0);
  });

  it('gives every feature a unique slug, a sane date range, and a closed polygon ring', () => {
    const seen = new Set();
    for (const feature of politiesAsset.features) {
      const { s, n, from, to } = feature.properties;
      expect(seen.has(s), `duplicate polity slug "${s}"`).toBe(false);
      seen.add(s);
      expect(typeof n).toBe('string');
      expect(from).toBeLessThan(to);

      expect(['Polygon', 'MultiPolygon']).toContain(feature.geometry.type);
      for (const ring of ringsOf(feature)) {
        expect(ring.length).toBeGreaterThanOrEqual(4);
        const [firstLon, firstLat] = ring[0];
        const [lastLon, lastLat] = ring[ring.length - 1];
        expect(firstLon).toBe(lastLon);
        expect(firstLat).toBe(lastLat);
        for (const [lon, lat] of ring) {
          expect(lon).toBeGreaterThanOrEqual(-180);
          expect(lon).toBeLessThanOrEqual(180);
          expect(lat).toBeGreaterThanOrEqual(-90);
          expect(lat).toBeLessThanOrEqual(90);
        }
      }
    }
  });

  it('every battle override references a polity slug that actually exists', () => {
    const slugs = new Set(politiesAsset.features.map((f) => f.properties.s));
    for (const [eventSlug, override] of Object.entries(atlasOverrides)) {
      for (const key of ['att', 'def']) {
        if (override[key]) {
          expect(slugs.has(override[key]), `${eventSlug}.${key} -> unknown polity "${override[key]}"`).toBe(true);
        }
      }
    }
  });
});

describe('politiesForYear', () => {
  it('includes a polity for the entire span it covers, not just a single year', () => {
    const babylon = politiesAsset.features.find((f) => f.properties.s === 'babylon');
    const { from, to } = babylon.properties;
    expect(politiesForYear(politiesAsset.features, from).map((f) => f.properties.s)).toContain('babylon');
    expect(politiesForYear(politiesAsset.features, to).map((f) => f.properties.s)).toContain('babylon');
    expect(politiesForYear(politiesAsset.features, from - 1).map((f) => f.properties.s)).not.toContain('babylon');
    expect(politiesForYear(politiesAsset.features, to + 1).map((f) => f.properties.s)).not.toContain('babylon');
  });
});

// The point of the coastline clip: before it, every territory was a 4-7 point
// box whose edges ran straight out to sea, over the Dead Sea, and across the
// Sea of Galilee. These are the regression guards for that — geometry checks a
// schema test cannot express.
describe('atlas-polities.json coastline clipping', () => {
  it('keeps each polity off the water it borders', () => {
    expect(inFeature([34.40, 32.05], polity('canaan'))).toBe(false); // Mediterranean off Joppa
    expect(inFeature([34.30, 31.65], polity('philistia'))).toBe(false); // Mediterranean off Ashkelon
    expect(inFeature([33.20, 28.50], polity('egypt'))).toBe(false); // Gulf of Suez
    expect(inFeature([51.00, 27.00], polity('persia'))).toBe(false); // Persian Gulf
  });

  it('punches the Dead Sea and the Sea of Galilee through as holes', () => {
    expect(inFeature([35.47, 31.50], polity('judah'))).toBe(false); // Dead Sea
    expect(inFeature([35.47, 31.50], polity('canaan'))).toBe(false);
    expect(inFeature([35.58, 32.82], polity('canaan'))).toBe(false); // Sea of Galilee
  });

  it('still contains every capital and major city it should', () => {
    // The failure mode worth guarding: Sutherland-Hodgman is exact only for a
    // convex clip region, and a concave extent silently loses area. That is
    // how Jerusalem briefly fell outside Judah while this was being built.
    expect(inFeature([35.23, 31.78], polity('judah'))).toBe(true); // Jerusalem
    expect(inFeature([35.10, 31.53], polity('judah'))).toBe(true); // Hebron
    expect(inFeature([35.20, 32.28], polity('israel'))).toBe(true); // Samaria
    expect(inFeature([35.28, 32.21], polity('canaan'))).toBe(true); // Shechem
    expect(inFeature([34.47, 31.50], polity('philistia'))).toBe(true); // Gaza
    expect(inFeature([36.29, 33.51], polity('aram'))).toBe(true); // Damascus
    expect(inFeature([31.25, 29.85], polity('egypt'))).toBe(true); // Memphis
    expect(inFeature([43.15, 36.36], polity('assyria'))).toBe(true); // Nineveh
    expect(inFeature([44.42, 32.54], polity('babylon'))).toBe(true); // Babylon
    expect(inFeature([48.25, 32.19], polity('persia'))).toBe(true); // Susa
  });

  it('carries enough detail to read as a coastline rather than a box', () => {
    const points = politiesAsset.features
      .reduce((n, f) => n + ringsOf(f).reduce((m, r) => m + r.length, 0), 0);
    expect(points).toBeGreaterThan(1200); // was 74 across all 13 polities
  });
});

describe('atlas-polity-extents.json', () => {
  it('describes the same polities as the generated asset', () => {
    const generated = politiesAsset.features.map((f) => f.properties.s).sort();
    const extents = extentsAsset.features.map((f) => f.properties.s).sort();
    expect(extents).toEqual(generated);
  });

  it('keeps every extent convex, which the clip depends on for correctness', () => {
    // scripts/build-atlas-polities.js throws on a concave extent; this catches
    // it in the test suite rather than only at build time.
    for (const feature of extentsAsset.features) {
      const ring = feature.geometry.coordinates[0].slice(0, -1);
      const cross = (o, a, b) => (a[0] - o[0]) * (b[1] - o[1]) - (a[1] - o[1]) * (b[0] - o[0]);
      let positive = 0;
      let negative = 0;
      for (let i = 0; i < ring.length; i += 1) {
        const turn = cross(ring[i], ring[(i + 1) % ring.length], ring[(i + 2) % ring.length]);
        if (turn > 1e-9) positive += 1;
        else if (turn < -1e-9) negative += 1;
      }
      expect(positive && negative, `"${feature.properties.s}" extent is not convex`).toBeFalsy();
    }
  });
});
